/* Analytics : activité, finance, patients, traitements */
(function () {
  const N = Nacre, D = N.D, A = N.App, H = A.H;
  const { icon, fmt, esc, avatar, badge } = N.ui;
  const AN = { tab: 'activite', range: 12 };

  function heatmap(ap) {
    const days = ['Lun', 'Mar', 'Mer', 'Jeu', 'Ven', 'Sam']; const hours = [8, 9, 10, 11, 12, 14, 15, 16, 17, 18];
    const grid = days.map((_, di) => hours.map(h => ap.filter(a => D.parse(a.date).getDay() === di + 1 && Math.floor(D.min(a.start) / 60) === h && a.status !== 'annule').length));
    const max = Math.max(1, ...grid.flat());
    return `<div style="overflow-x:auto"><table style="border-collapse:separate;border-spacing:4px;width:100%;min-width:480px"><thead><tr><th></th>${hours.map(h => `<th class="xs faint" style="font-weight:500">${h}h</th>`).join('')}</tr></thead><tbody>${grid.map((row, i) => `<tr><td class="xs muted" style="padding-right:6px">${days[i]}</td>${row.map((v, j) => `<td title="${days[i]} ${hours[j]}h : ${v} RDV" style="height:28px;border-radius:6px;background:rgba(44,107,203,${(0.06 + v / max * .85).toFixed(2)});text-align:center;font-size:11px;color:${v / max > .55 ? '#fff' : 'var(--ink-2)'}">${v || ''}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
  }

  A.view('analytics', {
    render() {
      const S = N.S; const cl = S.session.clinic; const hist0 = cl === 'all' ? N.sumHist() : S.history[cl]; const hist = hist0.slice(-AN.range);
      const L = hist.map(h => fmt.mshort(h.m)); const last = hist[hist.length - 1], prev = hist[hist.length - 2];
      const t = D.todayYmd(); const from = D.addYmd(t, -60);
      const ap = S.appts.filter(a => N.inClinic(a) && a.date >= from && a.date <= t);
      const done = ap.filter(a => a.status === 'termine');
      const pct = (a, b) => Math.round((a / b - 1) * 1000) / 10;
      const tabs = `<div class="tabs mb-16">${[['activite', 'Activité', 'activity'], ['finance', 'Finance', 'wallet'], ['patients', 'Patients', 'users'], ['traitements', 'Traitements', 'clipboard']].map(([k, l, ic]) => `<button class="${AN.tab === k ? 'on' : ''}" data-an="${k}">${icon(ic).replace('<svg', '<svg style="width:15px;height:15px"')}${l}</button>`).join('')}</div>`;
      const head = H.head('Analytics', `${cl === 'all' ? 'Vue consolidée — 3 établissements' : esc(N.clinic(cl).name)} · graphiques interactifs`, `<div class="btn-group">${[[6, '6 mois'], [12, '12 mois']].map(([k, l]) => `<button data-range="${k}" class="${AN.range === k ? 'on' : ''}">${l}</button>`).join('')}</div><button class="btn" data-export>${icon('download')}Exporter CSV</button>`);
      let body = '';
      if (AN.tab === 'activite') {
        body = `<div class="grid g4 mb-16">${H.kpi('Consultations (mois)', fmt.num(last.consults), 'stethoscope', 'tone-blue', H.delta(pct(last.consults, prev.consults)))}${H.kpi('Nouveaux patients', last.newPatients, 'user', 'tone-teal', H.delta(pct(last.newPatients, prev.newPatients)))}${H.kpi('Patients récurrents', Math.round(last.recurrent / last.consults * 100) + ' %', 'repeat', 'tone-violet', '<span>des consultations</span>')}${H.kpi('Taux de remplissage', last.fill + ' %', 'target', 'tone-green', `<span>no-show ${fmt.pct(last.noshow)}</span>`)}</div>
        <div class="grid g2 mb-16"><div class="card"><div class="card-head"><h3>Consultations</h3><div class="legend"><span><i style="background:#2C6BCB"></i>Total</span><span><i style="background:#5E9F8D"></i>Patients récurrents</span></div></div><div class="card-body">${N.ui.lineChart({ labels: L, series: [{ name: 'Consultations', data: hist.map(h => h.consults), color: '#2C6BCB' }, { name: 'Récurrents', data: hist.map(h => h.recurrent), color: '#5E9F8D' }], height: 230 })}</div></div>
          <div class="card"><div class="card-head"><h3>Nouveaux patients</h3></div><div class="card-body">${N.ui.barChart({ labels: L, series: [{ name: 'Nouveaux patients', data: hist.map(h => h.newPatients), color: '#3AA6A0' }], height: 230 })}</div></div></div>
        <div class="grid g2"><div class="card"><div class="card-head"><h3>Taux de remplissage & no-show</h3><div class="legend"><span><i style="background:#12264A"></i>Remplissage</span><span><i style="background:#CF4759"></i>No-show</span></div></div><div class="card-body">${N.ui.lineChart({ labels: L, series: [{ name: 'Remplissage (%)', data: hist.map(h => h.fill), color: '#12264A' }, { name: 'No-show (%)', data: hist.map(h => h.noshow), color: '#CF4759', dash: true }], height: 220, fmtV: v => v + ' %' })}</div></div>
          <div class="card"><div class="card-head"><div><h3>Affluence par créneau</h3><div class="sub">60 derniers jours · rendez-vous par jour et heure</div></div></div><div class="card-body">${heatmap(ap)}</div></div></div>`;
      } else if (AN.tab === 'finance') {
        const byType = {}; done.forEach(a => byType[a.type] = (byType[a.type] || 0) + S.types[a.type].price);
        const inv = S.invoices.filter(i => N.inClinic(i)); const aging = [[0, 30], [31, 60], [61, 90], [91, 9999]].map(([a, b]) => inv.filter(i => { const d = D.diffDays(i.date, t); const due = N.invoiceTotal(i) - N.invoicePaid(i); return due > 0 && d >= a && d <= b; }).reduce((s, i) => s + N.invoiceTotal(i) - N.invoicePaid(i), 0));
        const pays = S.payments.filter(p => N.inClinic(p) && p.date >= from && p.amount > 0); const byM = {}; pays.forEach(p => byM[p.method] = (byM[p.method] || 0) + p.amount);
        const MC = { especes: '#5E9F8D', carte: '#2C6BCB', virement: '#12264A', en_ligne: '#B89457' };
        body = `<div class="grid g4 mb-16">${H.kpi('Chiffre d’affaires (mois)', fmt.money(last.revenue), 'trend', 'tone-gold', H.delta(pct(last.revenue, prev.revenue)))}${H.kpi('Panier moyen', fmt.money(last.revenue / last.consults), 'wallet', 'tone-blue', '<span>par consultation</span>')}${H.kpi('CA cumulé', fmt.money(hist.reduce((s, h) => s + h.revenue, 0)), 'bars', 'tone-navy', `<span>${AN.range} mois</span>`)}${H.kpi('Impayés', fmt.money(aging.reduce((a, b) => a + b, 0)), 'alert', 'tone-red', `<span>dont ${fmt.money(aging[3])} &gt; 90 j</span>`)}</div>
        <div class="card mb-16"><div class="card-head"><h3>Chiffre d’affaires mensuel</h3><div class="legend"><span><i style="background:#2C6BCB"></i>Cette année</span><span><i style="background:#D8DEE6"></i>Année précédente</span></div></div><div class="card-body">${N.ui.barChart({ labels: L, series: [{ name: 'Année précédente', data: hist.map(h => Math.round(h.revenue * .87 / 1000) * 1000), color: '#D8DEE6' }, { name: 'Cette année', data: hist.map(h => h.revenue), color: '#2C6BCB' }], height: 250, fmtV: fmt.money })}</div></div>
        <div class="grid g3"><div class="card"><div class="card-head"><h3>Revenus par traitement</h3><span class="xs muted">60 j</span></div><div class="card-body">${N.ui.hbars(Object.entries(byType).sort((a, b) => b[1] - a[1]).slice(0, 7).map(([k, v]) => ({ label: S.types[k].label, value: v, color: S.types[k].color })), { fmtV: fmt.money })}</div></div>
          <div class="card"><div class="card-head"><h3>Paiements par mode</h3><span class="xs muted">60 j</span></div><div class="card-body">${N.ui.donut({ data: Object.entries(byM).map(([k, v]) => ({ label: N.ui.METHOD[k], value: v, color: MC[k] })), center: fmt.k(Object.values(byM).reduce((a, b) => a + b, 0)), sub: 'DH', fmtV: fmt.money, size: 150 })}</div></div>
          <div class="card"><div class="card-head"><h3>Ancienneté des impayés</h3></div><div class="card-body">${N.ui.hbars([['0–30 jours', aging[0], 'var(--sage)'], ['31–60 jours', aging[1], 'var(--warning)'], ['61–90 jours', aging[2], '#E0582F'], ['+ de 90 jours', aging[3], 'var(--danger)']].map(([l, v, c]) => ({ label: l, value: v, color: c })), { fmtV: fmt.money })}</div></div></div>`;
      } else if (AN.tab === 'patients') {
        const pts = S.patients.filter(p => N.inClinic(p));
        const freq = {}; pts.forEach(p => { const n = S.appts.filter(a => a.patient === p.id && a.status === 'termine' && a.date >= from).length; const k = n === 0 ? '0' : n === 1 ? '1' : n <= 3 ? '2–3' : n <= 6 ? '4–6' : '7+'; freq[k] = (freq[k] || 0) + 1; });
        const ages = [['< 18', 0, 17], ['18–30', 18, 30], ['31–45', 31, 45], ['46–60', 46, 60], ['> 60', 61, 120]].map(([l, a, b]) => ({ label: l, value: pts.filter(p => { const x = N.age(p.dob); return x >= a && x <= b; }).length }));
        const ret = Math.round(pts.filter(p => S.appts.filter(a => a.patient === p.id && a.status === 'termine').length >= 2).length / (pts.length || 1) * 100);
        body = `<div class="grid g4 mb-16">${H.kpi('Patients actifs', pts.length, 'users', 'tone-blue')}${H.kpi('Taux de fidélisation', ret + ' %', 'heart', 'tone-red', '<span>≥ 2 visites</span>')}${H.kpi('Fréquence moyenne', (done.length / (new Set(done.map(a => a.patient)).size || 1)).toFixed(1).replace('.', ',') + ' visites', 'repeat', 'tone-violet', '<span>par patient (60 j)</span>')}${H.kpi('Réservations en ligne', Math.round(S.appts.filter(a => N.inClinic(a) && a.source === 'online').length / (S.appts.filter(a => N.inClinic(a) && a.date > t).length || 1) * 100) + ' %', 'globe', 'tone-teal', '<span>des RDV à venir</span>')}</div>
        <div class="grid g3"><div class="card"><div class="card-head"><h3>Acquisition</h3><span class="xs muted">Source déclarée</span></div><div class="card-body">${N.ui.donut({ data: [['Bouche-à-oreille', 38, '#12264A'], ['Google / Maps', 24, '#2C6BCB'], ['Réservation en ligne', 18, '#3AA6A0'], ['Réseaux sociaux', 12, '#B89457'], ['Adressé par confrère', 8, '#7568D1']].map(([l, v, c]) => ({ label: l, value: v, color: c })), center: '100', sub: '%', fmtV: v => v + ' %', size: 150 })}</div></div>
          <div class="card"><div class="card-head"><h3>Fréquence des visites</h3><span class="xs muted">60 j</span></div><div class="card-body">${N.ui.barChart({ labels: ['0', '1', '2–3', '4–6', '7+'], series: [{ name: 'Patients', data: ['0', '1', '2–3', '4–6', '7+'].map(k => freq[k] || 0), color: '#5E9F8D' }], height: 200 })}</div></div>
          <div class="card"><div class="card-head"><h3>Répartition par âge</h3></div><div class="card-body">${N.ui.hbars(ages, { color: 'var(--primary)' })}<div class="divider"></div><div class="row between small"><span>Femmes <b>${pts.filter(p => p.sex === 'F').length}</b></span><span>Hommes <b>${pts.filter(p => p.sex === 'M').length}</b></span></div></div></div></div>`;
      } else {
        const cnt = {}; done.forEach(a => cnt[a.type] = (cnt[a.type] || 0) + 1);
        const plans = S.plans.filter(p => N.inClinic(N.patient(p.patient))); const q = S.quotes.filter(x => N.inClinic(N.patient(x.patient)));
        const pc = s => plans.filter(p => p.status === s).length;
        body = `<div class="grid g4 mb-16">${H.kpi('Plans acceptés', plans.filter(p => p.status !== 'propose').length, 'check', 'tone-green', `<span>sur ${plans.length} proposés</span>`)}${H.kpi('Plans en cours', pc('encours') + pc('planifie'), 'activity', 'tone-blue')}${H.kpi('Plans terminés', pc('termine'), 'badge', 'tone-gold')}${H.kpi('Conversion des devis', Math.round(q.filter(x => x.status === 'accepte').length / (q.filter(x => x.status !== 'brouillon').length || 1) * 100) + ' %', 'trend', 'tone-violet')}</div>
        <div class="grid g2 mb-16"><div class="card"><div class="card-head"><h3>Traitements les plus réalisés</h3><span class="xs muted">60 derniers jours</span></div><div class="card-body">${N.ui.hbars(Object.entries(cnt).sort((a, b) => b[1] - a[1]).map(([k, v]) => ({ label: S.types[k].label, value: v, color: S.types[k].color })))}</div></div>
          <div class="card"><div class="card-head"><h3>Entonnoir des plans de traitement</h3></div><div class="card-body">${[['Proposés', plans.length, '#9AA5B4'], ['Acceptés', plans.filter(p => p.status !== 'propose').length, '#7568D1'], ['Planifiés / en cours', plans.filter(p => ['planifie', 'encours', 'termine'].includes(p.status)).length, '#2C6BCB'], ['Terminés', pc('termine'), '#2E9C6E']].map(([l, v, c], i, arr) => `<div style="margin:0 auto 8px;width:${100 - i * 14}%;background:${c};color:#fff;border-radius:10px;padding:12px 16px;display:flex;justify-content:space-between;font-weight:600;transition:width .5s"><span>${l}</span><span>${v}${i ? ` <span style="opacity:.75;font-weight:500">· ${Math.round(v / (arr[0][1] || 1) * 100)} %</span>` : ''}</span></div>`).join('')}<div class="small muted center mt-12">Valeur moyenne d’un plan : <b style="color:var(--ink)">${fmt.money(plans.reduce((s, p) => s + N.Plans.totals(p).total, 0) / (plans.length || 1))}</b></div></div></div></div>`;
      }
      const dent = N.dentists().map(d => { const x = S.appts.filter(a => a.dentist === d.id && a.date >= from && a.date <= t); const rv = S.reviews.filter(r => r.dentist === d.id); return `<tr><td>${H.pcell ? `<div class="row">${avatar(d, 'sm')}<div><b style="font-weight:500">${esc(N.name(d))}</b><div class="xs muted">${esc(d.spec)}</div></div></div>` : ''}</td><td class="num">${x.filter(a => a.status === 'termine').length}</td><td class="num">${fmt.money(x.filter(a => a.status === 'termine').reduce((s, a) => s + S.types[a.type].price, 0))}</td><td class="num">${fmt.pct(x.filter(a => a.status === 'noshow').length / (x.length || 1) * 100)}</td><td class="num">${new Set(x.map(a => a.patient)).size}</td><td class="num">★ ${(rv.reduce((s, r) => s + r.rating, 0) / (rv.length || 1)).toFixed(1).replace('.', ',')}</td></tr>`; }).join('');
      return head + tabs + body + `<div class="card mt-16"><div class="card-head"><div><h3>Statistiques par praticien</h3><div class="sub">60 derniers jours</div></div></div><div class="table-wrap"><table class="table"><thead><tr><th>Praticien</th><th class="num">Actes réalisés</th><th class="num">CA produit</th><th class="num">No-show</th><th class="num">Patients</th><th class="num">Satisfaction</th></tr></thead><tbody>${dent}</tbody></table></div></div>`;
    },
    mount(el) {
      el.querySelectorAll('[data-an]').forEach(b => b.onclick = () => { AN.tab = b.dataset.an; A.refresh(); });
      el.querySelectorAll('[data-range]').forEach(b => b.onclick = () => { AN.range = +b.dataset.range; A.refresh(); });
      el.querySelector('[data-export]').onclick = () => {
        const S = N.S; const cl = S.session.clinic; const hist = cl === 'all' ? N.sumHist() : S.history[cl];
        const csv = 'mois;chiffre_affaires;consultations;nouveaux_patients;taux_remplissage;no_show\n' + hist.map(h => [h.m.slice(0, 7), h.revenue, h.consults, h.newPatients, h.fill, h.noshow].join(';')).join('\n');
        const a = document.createElement('a'); a.href = URL.createObjectURL(new Blob(['﻿' + csv], { type: 'text/csv' })); a.download = 'nacre-analytics.csv'; a.click();
        N.log('Export analytics (CSV)', cl); N.save();
      };
    }
  });
})();
